package com.lolfm.simulator;import static org.junit.jupiter.api.Assertions.*;import com.lolfm.factory.DummyDataFactory;import org.junit.jupiter.api.Test;
class LateGameIntegrationTest{
 @Test void completeSimulationExposesLateGameAndClosesSchedules(){DummyDataFactory f=new DummyDataFactory();MatchSimulator sim=new MatchSimulator(new TeamfightResolver(),new EndGameEvaluator(),new SnapshotFactory(),new ObjectiveResolver(),new PostFightResolver(),new ObjectiveAttemptResolver(),new StructureResolver(),new PushResolver(),SimulationOptions.productionDefaults());var t=sim.simulate(f.createBlueTeam(),f.createRedTeam(),7L);var late=t.getSnapshots().stream().filter(x->x.getLateGame().matchPhase()==MatchPhase.LATE_GAME).findFirst().orElseThrow();assertNull(late.getLateGame().latestDecision());var end=t.getSnapshots().getLast();assertEquals(-1,end.getLateGame().nextEvaluationAtSeconds());assertEquals(LateGamePlanStatus.MATCH_ENDED,end.getLateGame().bluePlan().status());assertTrue(end.getPlayerSnapshots().stream().filter(p->p.getPosition()==com.lolfm.domain.Position.SUPPORT).allMatch(p->p.getCs()==0));}
 @Test void sameSeedProducesSameStructuredLateGameTimeline(){DummyDataFactory f=new DummyDataFactory();MatchSimulator sim=new MatchSimulator(new TeamfightResolver(),new EndGameEvaluator(),new SnapshotFactory(),new ObjectiveResolver(),new PostFightResolver(),new ObjectiveAttemptResolver(),new StructureResolver(),new PushResolver(),SimulationOptions.productionDefaults());var a=sim.simulate(f.createBlueTeam(),f.createRedTeam(),11L);f=new DummyDataFactory();var b=sim.simulate(f.createBlueTeam(),f.createRedTeam(),11L);assertEquals(a.getEvents().stream().map(e->e.getType()+":"+e.getLateGameDecision()+":"+e.getStructureActionSource()).toList(),b.getEvents().stream().map(e->e.getType()+":"+e.getLateGameDecision()+":"+e.getStructureActionSource()).toList());}
}
